from django.views import View
from django.http import FileResponse, Http404, HttpResponseForbidden
from django.contrib.auth.mixins import LoginRequiredMixin
from post_office.models import Attachment

class EmailAttachmentDownloadView(LoginRequiredMixin, View):
    def get(self, request, attachment_id):
        try:
            attachment = Attachment.objects.prefetch_related('emails').get(pk=attachment_id)
        except Attachment.DoesNotExist:
            raise Http404("Attachment not found")

        # Verify that at least one associated email belongs to the authenticated user
        user_emails = [request.user.email]
        has_access = attachment.emails.filter(to__overlap=user_emails).exists() or request.user.is_staff
        if not has_access:
            return HttpResponseForbidden("Access denied to this attachment")

        return FileResponse(attachment.file.open('rb'), as_attachment=True, filename=attachment.name)
